export const SplitExecutionRequestSchema = {
    properties: {
        quantity_a: {
            anyOf: [
                {
                    type: 'number',
                    exclusiveMinimum: 0
                },
                {
                    type: 'string',
                    pattern: '^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$'
                }
            ],
            title: 'Quantity A',
            description: 'Quantity of the first resulting execution'
        },
        quantity_b: {
            anyOf: [
                {
                    type: 'number',
                    exclusiveMinimum: 0
                },
                {
                    type: 'string',
                    pattern: '^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$'
                }
            ],
            title: 'Quantity B',
            description: 'Quantity of the second resulting execution'
        },
        price_a: {
            anyOf: [
                {
                    type: 'number',
                    minimum: 0
                },
                {
                    type: 'string',
                    pattern: '^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$'
                },
                {
                    type: 'null'
                }
            ],
            title: 'Price A',
            description: 'Price for the first execution'
        },
        price_b: {
            anyOf: [
                {
                    type: 'number',
                    minimum: 0
                },
                {
                    type: 'string',
                    pattern: '^(?!^[-+.]*$)[+-]?0*\\d*\\.?\\d*$'
                },
                {
                    type: 'null'
                }
            ],
            title: 'Price B',
            description: 'Price for the second execution'
        },
        executed_at_a: {
            anyOf: [
                {
                    type: 'string',
                    format: 'date-time'
                },
                {
                    type: 'null'
                }
            ],
            title: 'Executed At A',
            description: 'Timestamp for the first execution (UTC)'
        },
        executed_at_b: {
            anyOf: [
                {
                    type: 'string',
                    format: 'date-time'
                },
                {
                    type: 'null'
                }
            ],
            title: 'Executed At B',
            description: 'Timestamp for the second execution (UTC)'
        }
    },
    type: 'object',
    required: ['quantity_a', 'quantity_b'],
    title: 'SplitExecutionRequest',
    description: `Request payload for splitting one execution into two.

Both resulting executions share the same \`\`trade_id\`\` and \`\`origin='split'\`\`.
The original execution is soft-deleted (\`\`deleted=true\`\`).

Attributes:
    quantity_a: Quantity of the first resulting execution.
    quantity_b: Quantity of the second resulting execution.
        Must sum to the original execution's quantity.
    price_a: Price for the first execution (defaults to original price).
    price_b: Price for the second execution (defaults to original price).
    executed_at_a: Timestamp for the first execution (defaults to original).
    executed_at_b: Timestamp for the second execution (defaults to original).`
} as const;

